------------------------------------------------------------------------------
-- Helpers
------------------------------------------------------------------------------
local function OB_Char(x, y)
	-- y = 0 is the southern row; Rows are stored north first.
	local row = OB_MAP.Rows[OB_MAP.Height - y];
	if row == nil then return "~"; end
	local c = string.sub(row, x + 1, x + 1);
	if c == nil or c == "" then return "~"; end
	return c;
end

local function OB_Latitude(y)
	-- Approximate real latitude of a row (used for forests and jungles)
	local lat = OB_MAP.LatRows[y + 1];
	if lat == nil then return 40; end
	return lat;
end

function OB_Neighbors(x, y)
	if y % 2 == 0 then
		return {{x-1, y}, {x+1, y}, {x-1, y+1}, {x, y+1}, {x-1, y-1}, {x, y-1}};
	end
	return {{x-1, y}, {x+1, y}, {x, y+1}, {x+1, y+1}, {x, y-1}, {x+1, y-1}};
end

