function GetMapInitData(worldSize)
	return {
		Width = OB_MAP.Width,
		Height = OB_MAP.Height,
		WrapX = false,
	};
end
------------------------------------------------------------------------------
function GeneratePlotTypes()
	print("Ottoman Frontiers 1299: plot types");
	local plotTypes = {};
	local w, h = OB_MAP.Width, OB_MAP.Height;
	for y = 0, h - 1 do
		for x = 0, w - 1 do
			local i = y * w + x;
			local c = OB_Char(x, y);
			if c == "~" then
				plotTypes[i] = PlotTypes.PLOT_OCEAN;
			elseif c == "M" then
				plotTypes[i] = PlotTypes.PLOT_MOUNTAIN;
			elseif c == "G" or c == "P" or c == "D" or c == "T" then
				plotTypes[i] = PlotTypes.PLOT_HILLS;
			else
				plotTypes[i] = PlotTypes.PLOT_LAND;
			end
		end
	end
	SetPlotTypes(plotTypes);
	local args = {expansion_diceroll_table = {10, 6, 4}};
	GenerateCoasts(args);
end
------------------------------------------------------------------------------
local TERRAIN_BY_CHAR = {
	g = "TERRAIN_GRASS",  G = "TERRAIN_GRASS",
	p = "TERRAIN_PLAINS", P = "TERRAIN_PLAINS",
	d = "TERRAIN_DESERT", D = "TERRAIN_DESERT",
	t = "TERRAIN_TUNDRA", T = "TERRAIN_TUNDRA",
	s = "TERRAIN_SNOW",
};

local function MountainTerrain(x, y)
	local counts = {};
	for _, nb in ipairs(OB_Neighbors(x, y)) do
		local tt = TERRAIN_BY_CHAR[OB_Char(nb[1], nb[2])];
		if tt ~= nil then counts[tt] = (counts[tt] or 0) + 1; end
	end
	local best, bestN = "TERRAIN_PLAINS", 0;
	for tt, n in pairs(counts) do
		if n > bestN then best, bestN = tt, n; end
	end
	return best;
end

function GenerateTerrain()
	print("Ottoman Frontiers 1299: terrain");
	local terrainTypes = {};
	local w, h = OB_MAP.Width, OB_MAP.Height;
	for y = 0, h - 1 do
		for x = 0, w - 1 do
			local i = y * w + x;
			local plot = Map.GetPlot(x, y);
			if plot:IsWater() then
				terrainTypes[i] = plot:GetTerrainType();
			else
				local c = OB_Char(x, y);
				local sType = TERRAIN_BY_CHAR[c];
				if c == "M" then sType = MountainTerrain(x, y); end
				if sType == nil then sType = "TERRAIN_PLAINS"; end
				terrainTypes[i] = GameInfoTypes[sType];
			end
		end
	end
	SetTerrainTypes(terrainTypes);
end
------------------------------------------------------------------------------
-- Rivers come from the map data. Each entry: x, y, edge, flow
--   edge 1 = east edge (WOfRiver), 2 = south-east edge (NWOfRiver), 3 = south-west edge (NEOfRiver)
--   flow 0..5 = N, NE, SE, S, SW, NW
------------------------------------------------------------------------------
function AddRivers()
	print("Ottoman Frontiers 1299: rivers");
	local flows = {
		[0] = FlowDirectionTypes.FLOWDIRECTION_NORTH,
		[1] = FlowDirectionTypes.FLOWDIRECTION_NORTHEAST,
		[2] = FlowDirectionTypes.FLOWDIRECTION_SOUTHEAST,
		[3] = FlowDirectionTypes.FLOWDIRECTION_SOUTH,
		[4] = FlowDirectionTypes.FLOWDIRECTION_SOUTHWEST,
		[5] = FlowDirectionTypes.FLOWDIRECTION_NORTHWEST,
	};
	local count = 0;
	for _, r in ipairs(OB_MAP.Rivers) do
		local plot = Map.GetPlot(r[1], r[2]);
		if plot ~= nil and not plot:IsWater() then
			local flow = flows[r[4]];
			if r[3] == 1 then
				plot:SetWOfRiver(true, flow);
			elseif r[3] == 2 then
				plot:SetNWOfRiver(true, flow);
			else
				plot:SetNEOfRiver(true, flow);
			end
			count = count + 1;
		end
	end
	print("Ottoman Frontiers 1299: river edges placed: " .. count);
end
