function AddFeatures()
	print("Ottoman Frontiers 1299: features");
	local featuregen = FeatureGenerator.Create({rainfall = 2});
	featuregen.GetLatitudeAtPlot = function(self, iX, iY)
		return math.min(1, math.abs(OB_Latitude(iY)) / 90);
	end
	featuregen:AddFeatures();
end
------------------------------------------------------------------------------
-- Historic starts
------------------------------------------------------------------------------
local function IsValidStart(plot)
	if plot == nil then return false; end
	if plot:IsWater() or plot:IsMountain() or plot:IsImpassable() then return false; end
	if plot:GetTerrainType() == GameInfoTypes.TERRAIN_SNOW then return false; end
	if plot:GetFeatureType() == GameInfoTypes.FEATURE_ICE then return false; end
	return true;
end

local function StartScore(plot, iDist)
	local score = 100 - iDist * 10;
	local terrain = plot:GetTerrainType();
	if terrain == GameInfoTypes.TERRAIN_GRASS or terrain == GameInfoTypes.TERRAIN_PLAINS then score = score + 15; end
	if terrain == GameInfoTypes.TERRAIN_DESERT then
		score = score - 10;
		if plot:IsRiver() then score = score + 15; end
	end
	if terrain == GameInfoTypes.TERRAIN_TUNDRA then score = score - 15; end
	if plot:IsRiver() then score = score + 10; end
	if plot:IsCoastalLand() then score = score + 8; end
	if plot:IsHills() then score = score + 5; end
	return score;
end

-- Searches over land from (tx, ty) for the best start that keeps the given distances.
-- blockers: list of {x, y, minDistance}
local function FindSite(tx, ty, blockers, maxRadius)
	local w, h = OB_MAP.Width, OB_MAP.Height;
	local sx, sy = nil, nil;
	for radius = 0, 4 do
		for y = math.max(0, ty - radius), math.min(h - 1, ty + radius) do
			for x = math.max(0, tx - radius), math.min(w - 1, tx + radius) do
				if sx == nil and Map.PlotDistance(x, y, tx, ty) == radius and not Map.GetPlot(x, y):IsWater() then
					sx, sy = x, y;
				end
			end
		end
		if sx ~= nil then break; end
	end
	if sx == nil then return nil; end

	local bestPlot, bestScore, bestDist = nil, -9999, nil;
	local dist = {};
	local queue = {{sx, sy}};
	dist[sy * w + sx] = 0;
	local head = 1;
	while head <= #queue do
		local cx, cy = queue[head][1], queue[head][2];
		head = head + 1;
		local d = dist[cy * w + cx];
		if bestDist ~= nil and d > bestDist + 1 then break; end
		local plot = Map.GetPlot(cx, cy);
		if IsValidStart(plot) then
			local ok = true;
			for _, b in ipairs(blockers) do
				if Map.PlotDistance(cx, cy, b[1], b[2]) < b[3] then ok = false; break; end
			end
			if ok then
				local sc = StartScore(plot, d);
				if sc > bestScore then
					bestPlot, bestScore = plot, sc;
					if bestDist == nil then bestDist = d; end
				end
			end
		end
		if d < maxRadius then
			for _, nb in ipairs(OB_Neighbors(cx, cy)) do
				local nx, ny = nb[1], nb[2];
				if nx >= 0 and nx < w and ny >= 0 and ny < h and dist[ny * w + nx] == nil then
					if not Map.GetPlot(nx, ny):IsWater() then
						dist[ny * w + nx] = d + 1;
						table.insert(queue, {nx, ny});
					end
				end
			end
		end
	end
	return bestPlot;
end

local function CivTypeOfPlayer(iPlayer)
	local pPlayer = Players[iPlayer];
	if pPlayer == nil or not pPlayer:IsEverAlive() then return nil; end
	local info = GameInfo.Civilizations[pPlayer:GetCivilizationType()];
	if info == nil then return nil; end
	return info.Type;
end

-- Sites of the extra 1299 cities of every civilization present in this game.
local function ReservedCitySites()
	local present = {};
	for iPlayer = 0, GameDefines.MAX_MAJOR_CIVS - 1 do
		local t = CivTypeOfPlayer(iPlayer);
		if t ~= nil then present[t] = true; end
	end
	local out = {};
	for civType, cities in pairs(OB_MAP.ScenarioCities) do
		if present[civType] then
			for i, c in ipairs(cities) do
				if i > 1 then table.insert(out, {c[1], c[2]}); end
			end
		end
	end
	return out;
end

local function ApplyHistoricStarts(start_plot_database)
	local MIN_DISTANCE = 6;
	local civToPlayers = {};
	for iPlayer = 0, GameDefines.MAX_MAJOR_CIVS - 1 do
		local t = CivTypeOfPlayer(iPlayer);
		if t ~= nil then
			civToPlayers[t] = civToPlayers[t] or {};
			table.insert(civToPlayers[t], iPlayer);
		end
	end

	local relocate, isRelocated = {}, {};
	for _, entry in ipairs(OB_MAP.MajorStarts) do
		local list = civToPlayers[entry[1]];
		if list ~= nil then
			for _, iPlayer in ipairs(list) do
				if not isRelocated[iPlayer] then
					table.insert(relocate, {iPlayer, entry[2], entry[3]});
					isRelocated[iPlayer] = true;
				end
			end
		end
	end
	if #relocate == 0 then return; end

	local blockers = {};
	for iPlayer = 0, GameDefines.MAX_MAJOR_CIVS - 1 do
		local pPlayer = Players[iPlayer];
		if pPlayer ~= nil and pPlayer:IsEverAlive() and not isRelocated[iPlayer] then
			local plot = pPlayer:GetStartingPlot();
			if plot ~= nil then table.insert(blockers, {plot:GetX(), plot:GetY(), MIN_DISTANCE}); end
		end
	end
	-- Starts keep 4 tiles away from the extra 1299 cities of other civilizations.
	for _, s in ipairs(ReservedCitySites()) do
		table.insert(blockers, {s[1], s[2], 4});
	end

	for _, r in ipairs(relocate) do
		local iPlayer, tx, ty = r[1], r[2], r[3];
		local bestPlot = FindSite(tx, ty, blockers, 18);
		if bestPlot ~= nil then
			Players[iPlayer]:SetStartingPlot(bestPlot);
			table.insert(blockers, {bestPlot:GetX(), bestPlot:GetY(), MIN_DISTANCE});
			-- Let city-state and resource placement see the new start
			if start_plot_database ~= nil and start_plot_database.PlaceImpactAndRipples ~= nil then
				pcall(function() start_plot_database:PlaceImpactAndRipples(bestPlot:GetX(), bestPlot:GetY()); end);
			end
			print("Ottoman Frontiers 1299: player " .. iPlayer .. " starts at its historic site (" .. bestPlot:GetX() .. "," .. bestPlot:GetY() .. ")");
		else
			local plot = Players[iPlayer]:GetStartingPlot();
			if plot ~= nil then table.insert(blockers, {plot:GetX(), plot:GetY(), MIN_DISTANCE}); end
		end
	end
end

-- Moves city-states that have a home on this map to it. Runs right after the
-- city-states are placed, before luxuries and bonus resources are distributed.
local function RelocateCityStates(self)
	local blockers = {};
	for iPlayer = 0, GameDefines.MAX_MAJOR_CIVS - 1 do
		local pPlayer = Players[iPlayer];
		if pPlayer ~= nil and pPlayer:IsEverAlive() then
			local plot = pPlayer:GetStartingPlot();
			if plot ~= nil then table.insert(blockers, {plot:GetX(), plot:GetY(), 5}); end
		end
	end
	for _, s in ipairs(ReservedCitySites()) do
		table.insert(blockers, {s[1], s[2], 3});
	end

	local iW = OB_MAP.Width;
	local moves = {};
	for n = 1, self.iNumCityStates do
		if self.city_state_validity_table[n] then
			local iPlayer = n + GameDefines.MAX_MAJOR_CIVS - 1;
			local pPlayer = Players[iPlayer];
			local sType = nil;
			if pPlayer ~= nil then
				pcall(function() sType = GameInfo.MinorCivilizations[pPlayer:GetMinorCivType()].Type; end);
			end
			local site = sType and OB_MAP.MinorSites[sType];
			if site ~= nil then
				table.insert(moves, {n, iPlayer, site[1], site[2]});
			else
				local plot = pPlayer and pPlayer:GetStartingPlot();
				if plot ~= nil then table.insert(blockers, {plot:GetX(), plot:GetY(), 3}); end
			end
		end
	end

	for _, m in ipairs(moves) do
		local n, iPlayer, tx, ty = m[1], m[2], m[3], m[4];
		local plot = FindSite(tx, ty, blockers, 10);
		if plot ~= nil then
			local x, y = plot:GetX(), plot:GetY();
			Players[iPlayer]:SetStartingPlot(plot);
			local old = self.cityStatePlots[n];
			self.cityStatePlots[n] = {x, y, old and old[3] or -1};
			pcall(function()
				self:PlaceResourceImpact(x, y, 5, 4);
				self:PlaceResourceImpact(x, y, 2, 3);
				self:PlaceResourceImpact(x, y, 1, 0);
				self:PlaceResourceImpact(x, y, 3, 3);
				self:PlaceResourceImpact(x, y, 4, 3);
				self:PlaceResourceImpact(x, y, 7, 3);
				self.playerCollisionData[y * iW + x + 1] = true;
			end);
			table.insert(blockers, {x, y, 3});
			print("Ottoman Frontiers 1299: city-state " .. iPlayer .. " placed at its historic site (" .. x .. "," .. y .. ")");
		else
			local p = Players[iPlayer]:GetStartingPlot();
			if p ~= nil then table.insert(blockers, {p:GetX(), p:GetY(), 3}); end
		end
	end
end
------------------------------------------------------------------------------
function StartPlotSystem()
	local startOption = Map.GetCustomOption(1);
	local res = Map.GetCustomOption(2);
	if res == 6 then
		res = 1 + Map.Rand(3, "Random Resources Option - Lua");
	end
	local bHistoric = (startOption ~= 2);

	print("Ottoman Frontiers 1299: start positions (historic = " .. tostring(bHistoric) .. ")");
	local start_plot_database = AssignStartingPlots.Create();

	local args = {
		method = 2,
		resources = res,
	};
	start_plot_database:GenerateRegions(args);
	start_plot_database:ChooseLocations();
	start_plot_database:BalanceAndAssign();

	if bHistoric then
		ApplyHistoricStarts(start_plot_database);
		local placeCityStates = start_plot_database.PlaceCityStates;
		start_plot_database.PlaceCityStates = function(self)
			placeCityStates(self);
			local ok, err = pcall(RelocateCityStates, self);
			if not ok then print("Ottoman Frontiers 1299: city-state relocation failed: " .. tostring(err)); end
		end
	end

	start_plot_database:PlaceNaturalWonders();
	start_plot_database:PlaceResourcesAndCityStates();
end
